def priority_fn(item_size, open_bin_remaining_capacities, capacity):
    scores = []
    for rem in open_bin_remaining_capacities:
        new_rem = rem - item_size
        if new_rem == 0:
            score = 1e6
        else:
            # Best Fit variant with penalty for leaving awkward small gaps
            # that are unlikely to be filled.
            score = (capacity - new_rem) ** 2
            if new_rem < 0.1 * capacity:
                score -= 50.0 * (0.1 * capacity - new_rem)
        scores.append(float(score))
    # Score for opening a new bin
    scores.append(-1.0)
    return scores
